#!/usr/bin/env python3
"""Generate all scenario catalog JSON files.

Creates 10 category files with 20 scenarios each (+ adversarial with 30),
plus 28 CAS pattern scenarios. Total: ~248 scenarios.
"""

import json
from pathlib import Path

OUT = Path(__file__).parent

def save(name: str, scenarios: list[dict], metadata: dict | None = None):
    data = {"metadata": metadata or {"name": name, "category": name}, "scenarios": scenarios}
    (OUT / f"{name}.json").write_text(json.dumps(data, indent=2))
    print(f"  {name}.json: {len(scenarios)} scenarios")

# ── Healthcare (20) ──────────────────────────────────────────────

