# Generate remaining categories more concisely
def gen_category(name, title, prompts_data, default_ops, default_doms, default_drives):
    scenarios = []
    for i, (sid, stitle, prompt, what) in enumerate(prompts_data):
        scenarios.append({"id":sid,"title":stitle,"category":name,"group":None,"prompt_text":prompt,"target_operators":default_ops,"target_domains":default_doms,"target_drives":default_drives,"difficulty":["easy","moderate","hard","moderate"][i%4],"what_it_tests":what,"success_indicator":"Demonstrates balanced reasoning across targeted operators and domains.","failure_indicator":"Shows significant gaps in the targeted cognitive dimensions."})
    save(name, scenarios, {"name":title,"category":name,"count":len(scenarios)})

